import { useState } from 'react'
import { parseTimeline, totalFrames } from '@fgcnote/shared/recording/recording-timeline'
import type { ReversalCatalogue } from '@fgcnote/shared/recording/reversal-catalogue'
import type { RecordingCardLocal, TrainingPresetApplyOutcome } from '@shared/types'
import type {
  TrainingPresetRead,
  TrainingPresetWrite
} from '@fgcnote/shared/recording/training-preset'
import { useI18n } from '../lib/i18n/use-i18n'
import { RecordingTimeline, type ObservationRegistryLookup } from '../lib/RecordingTimeline'
import { EmptyState } from '../lib/ui/EmptyState'
import { Notice } from '../lib/ui/Notice'
import { ObservationListDialog } from '../lib/ObservationListDialog'
import { TrainingPresetEditor } from '../lib/TrainingPresetEditor'
import {
  blankTrainingPresetDraft,
  type TrainingPresetDraft
} from '../lib/training-preset-draft'
import type { LiveTrainingPresetDraftResult } from '../lib/training-preset-live'
import { TimelineEditorDialog } from '../lib/TimelineEditorDialog'

/**
 * 資料庫 Library — browse the saved recording collection.
 *
 * Charter: desktop/SCREENS.md § Library（資料庫）. This renderer-owned cold-data
 * surface manages the signed-in user's cloud Recordings and TrainingPresets;
 * main receives only the strict projections and placement snapshots needed by
 * live bridge operations. Recordings stay grouped by character, the axis a
 * player uses to find them, rather than by their Firestore path.
 */
interface Props {
  records: RecordingCardLocal[]
  registry: ObservationRegistryLookup
  catalogue: ReversalCatalogue | null
  presets: TrainingPresetRead[]
  modReady: boolean
  onCreatePresetFromLive: () => Promise<LiveTrainingPresetDraftResult>
  onApplyPreset: (preset: TrainingPresetRead) => Promise<TrainingPresetApplyOutcome>
  onSavePreset: (preset: TrainingPresetWrite, exists: boolean) => Promise<void>
  onDeletePreset: (presetId: string) => Promise<void>
  onUpdateRecording: (
    recording: RecordingCardLocal,
    patch: { title?: string; timeline?: string[] }
  ) => Promise<boolean>
  onDeleteRecording: (recordingId: string) => Promise<void>
}

const DIM = 'm-0 text-xs leading-[1.55] text-muted-foreground'

function RecordingCard({
  record,
  registry,
  onRename,
  onEdit,
  onDelete
}: {
  record: RecordingCardLocal
  registry: ObservationRegistryLookup
  onRename: (title: string) => Promise<boolean>
  onEdit: () => void
  onDelete: () => Promise<void>
}) {
  const steps = parseTimeline(record.timeline, record.controllerMode)
  const [renaming, setRenaming] = useState(false)
  const [title, setTitle] = useState(record.title)
  const [failure, setFailure] = useState<string | null>(null)

  return (
    <article className="flex flex-col gap-2 rounded-[10px] border border-border bg-card p-[0.85rem]">
      <header className="flex items-baseline justify-between gap-2">
        <span
          title={record.title}
          className="min-w-0 overflow-hidden text-ellipsis whitespace-nowrap text-sm font-semibold"
        >
          {record.title}
        </span>
        <span className="flex-none text-xs tabular-nums text-muted-foreground">
          {totalFrames(steps)}f
        </span>
      </header>
      <RecordingTimeline record={record} registry={registry} expandable />
      {failure ? <p className="text-xs text-danger-fg">{failure}</p> : null}
      <footer className="mt-auto flex flex-wrap gap-2">
        {renaming ? (
