import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { defineConfig, externalizeDepsPlugin } from 'electron-vite'
import { loadEnv, type Plugin } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

/**
 * React Fast Refresh installs itself from an *inline* `<script type="module">`
 * that @vitejs/plugin-react adds to the dev server's HTML. index.html's CSP is
 * `script-src 'self'` with no 'unsafe-inline', so without this the dev window
 * comes up blank — the only evidence being a CSP violation in devtools.
 *
 * Scoped to `serve` on purpose. A packaged build has no preamble and must keep
 * the strict policy, so this must never be "fixed" by editing index.html.
 */
function devCspForReactRefresh(): Plugin {
  return {
    name: 'fgcnote:dev-csp-for-react-refresh',
    apply: 'serve',
    transformIndexHtml: {
      order: 'pre',
      handler: (html) => html.replace("script-src 'self'", "script-src 'self' 'unsafe-inline'")
    }
  }
}

/**
 * Three separate builds, one per Electron process:
 *   main    -> out/main/index.js     (Node context, privileged)
 *   preload -> out/preload/index.js  (bridge, contextIsolated)
 *   renderer-> out/renderer/         (Chromium, the app UI)
 *
 * externalizeDepsPlugin keeps node_modules out of the main/preload bundles so
 * native and Node built-in imports resolve at runtime instead of being inlined.
 *
 * @fgcnote/shared is the one exception. It is a workspace symlink to compiled
 * dist/ JS rather than a published package, so leaving it external turns into a
 * bare require() at runtime: fine in dev where node_modules is on disk, broken
 * the moment the app is packaged without it. Excluding it makes Rollup inline
 * it, so out/main stays a self-contained bundle.
 *
 * Import it via subpaths (`@fgcnote/shared/recording/recording-timeline`), never
 * the root barrel — the barrel re-exports the TipTap/ProseMirror tree, and
 * shared does not yet declare `sideEffects: false`, so a barrel import drags
 * hundreds of KB into an app that has no editor.
 */
function googleDesktopClientSecret(mode: string): string {
  const env = loadEnv(mode, process.cwd(), '')
  if (env.FGCNOTE_GOOGLE_DESKTOP_CLIENT_SECRET?.trim()) {
    return env.FGCNOTE_GOOGLE_DESKTOP_CLIENT_SECRET.trim()
  }

  const jsonPath = env.FGCNOTE_GOOGLE_DESKTOP_CLIENT_JSON?.trim()
  if (!jsonPath) return ''
  const parsed: unknown = JSON.parse(readFileSync(resolve(jsonPath), 'utf8'))
  const installed =
    typeof parsed === 'object' && parsed !== null && 'installed' in parsed
      ? (parsed as { installed?: unknown }).installed
      : null
  const secret =
    typeof installed === 'object' && installed !== null && 'client_secret' in installed
      ? (installed as { client_secret?: unknown }).client_secret
      : null
  if (typeof secret !== 'string' || !secret.trim()) {
    throw new Error('FGCNOTE_GOOGLE_DESKTOP_CLIENT_JSON has no installed.client_secret')
  }
  return secret.trim()
}

export default defineConfig(({ mode }) => ({
  main: {
    define: {
      __FGCNOTE_GOOGLE_DESKTOP_CLIENT_SECRET__: JSON.stringify(
        googleDesktopClientSecret(mode)
      )
    },
    plugins: [externalizeDepsPlugin({ exclude: ['@fgcnote/shared'] })],
    resolve: {
      alias: { '@shared': resolve('src/shared') }
    }
  },
  preload: {
    // Preload imports only *types* from shared, which are erased at compile
    // time, so it stays a pure IPC forwarder with nothing bundled.
    plugins: [externalizeDepsPlugin()],
    resolve: {
      alias: { '@shared': resolve('src/shared') }
    }
  },
  renderer: {
    root: 'src/renderer',
    build: {
      rollupOptions: {
        input: resolve('src/renderer/index.html')
      }
    },
    resolve: {
      alias: {
        '@shared': resolve('src/shared'),
        // shadcn/ui generates imports rooted at '@'. Mirrored in tsconfig.web.json.
        '@': resolve('src/renderer/src')
      }
    },
    // Vite does not pre-bundle linked workspace packages consistently;
    // excluding it stops a stale optimized copy surviving a tsc rebuild of dist/.
    optimizeDeps: { exclude: ['@fgcnote/shared'] },
    plugins: [react(), tailwindcss(), devCspForReactRefresh()]
  }
}))

